  border: 1px solid oklch(0.92 0 0);
  border-radius: 1rem;
  padding: 2rem;
  box-shadow: 0 4px 12px oklch(0 0 0 / 0.08);
  transition: all 0.3s ease;
  animation: slideInUp 0.5s ease-out;
}

.nutrition-card:hover {
  box-shadow: 0 6px 20px oklch(0 0 0 / 0.12);
  transform: translateY(-2px);
}

.nutrition-header {
  font-size: 1.5rem;
  font-weight: 600;
  font-family: var(--font-serif);
  color: var(--color-foreground);
  text-align: center;
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
}

.nutrition-calories {
  text-align: center;
  margin-bottom: 2rem;
  padding: 1.5rem;
  background: oklch(0.98 0 0);
  border-radius: 0.75rem;
  border: 2px solid oklch(0.6 0.15 145);
}

.nutrition-calories-value {
  font-size: 3rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: oklch(0.4 0.12 145);
  line-height: 1;
  margin-bottom: 0.5rem;
}

.nutrition-calories-label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-muted-foreground);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.nutrition-macros-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

.nutrition-macro-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 1rem;
  border-radius: 0.75rem;
  background: oklch(0.98 0 0);
  transition: all 0.3s ease;
}

.nutrition-macro-item:hover {
  transform: scale(1.05);
  background: oklch(0.96 0 0);
}

.nutrition-macro-item:nth-child(1) {
  animation-delay: 0.1s;
}

.nutrition-macro-item:nth-child(2) {
  animation-delay: 0.2s;
}

.nutrition-macro-item:nth-child(3) {
  animation-delay: 0.3s;
}

.nutrition-circle-progress {
  position: relative;
  width: 100px;
  height: 100px;
  margin-bottom: 1rem;
}

.nutrition-circle-background {
  fill: none;
  stroke: oklch(0.95 0 0);
  stroke-width: 8;
}

.nutrition-circle-fill {
  fill: none;
  stroke-width: 8;
  stroke-linecap: round;
  transform: rotate(-90deg);
  transform-origin: 50% 50%;
  transition: stroke-dashoffset 1s ease-out;
  animation: fillProgress 1.5s ease-out;
}

.nutrition-circle-fill.nutrition-protein {
  stroke: oklch(0.45 0.15 120);
}

.nutrition-circle-fill.nutrition-carbs {
  stroke: oklch(0.55 0.2 60);
}

.nutrition-circle-fill.nutrition-fats {
  stroke: oklch(0.35 0.1 30);
}

.nutrition-circle-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 1.5rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--color-foreground);
}

.nutrition-macro-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-foreground);
  margin-bottom: 0.25rem;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nutrition-macro-value {
  font-size: 1.125rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--color-muted-foreground);
}

.nutrition-serving-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: 1.5rem;
  background: oklch(0.95 0.05 60);
  border: 1px solid oklch(0.6 0.15 60);
  font-size: 0.75rem;
  font-weight: 600;
  color: oklch(0.3 0.1 60);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin: 0 auto;
  display: flex;
  justify-content: center;
}

@keyframes slideInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fillProgress {
  from {
    stroke-dashoffset: 283;
  }
}

/* Responsive adjustments for nutrition card */
@media (max-width: 768px) {
  .nutrition-card {
    padding: 1.5rem;
  }

  .nutrition-macros-grid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .nutrition-circle-progress {
    width: 80px;
    height: 80px;
  }

  .nutrition-circle-text {
    font-size: 1.25rem;
  }

  .nutrition-calories-value {
    font-size: 2.5rem;
  }
}

@media (max-width: 640px) {
  .nutrition-macros-grid {
    grid-template-columns: 1fr;
  }
}

/* Respect reduced motion preferences */
@media (prefers-reduced-motion: reduce) {
  .nutrition-card,
  .nutrition-macro-item,
  .nutrition-circle-fill {
    animation: none;
    transition: none;
  }

  .nutrition-card:hover,
  .nutrition-macro-item:hover {
    transform: none;
  }
}

