  --chart-2: oklch(0.6 0.118 184.704);
  --chart-3: oklch(0.398 0.07 227.392);
  --chart-4: oklch(0.828 0.189 84.429);
  --chart-5: oklch(0.769 0.188 70.08);
  --radius: 0.625rem;
  --sidebar: oklch(0.985 0 0);
  --sidebar-foreground: oklch(0.145 0 0);
  --sidebar-primary: oklch(0.205 0 0);
  --sidebar-primary-foreground: oklch(0.985 0 0);
  --sidebar-accent: oklch(0.97 0 0);
  --sidebar-accent-foreground: oklch(0.205 0 0);
  --sidebar-border: oklch(0.922 0 0);
  --sidebar-ring: oklch(0.708 0 0);
}

@theme inline {
  /* Typography */
  --font-sans: ui-sans-serif, system-ui, sans-serif, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol",
    "Noto Color Emoji";
  --font-serif: ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Consolas, "Liberation Mono", Menlo, monospace;

  /* Colors - Elegant khaki base with subtle cherry red accents */
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-muted: oklch(0.97 0 0);
  --color-muted-foreground: oklch(0.556 0 0);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);

  /* Primary khaki tones */
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);

  /* Subtle cherry red accent */
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);

  /* Secondary warm tones */
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);

  /* Destructive (keeping cherry red theme) */
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);

  /* Card and popover */
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);

  /* Border radius */
  --radius: var(--radius);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);

  /* Sidebar */
  --color-sidebar: var(--sidebar);
  --color-sidebar-foreground: var(--sidebar-foreground);
  --color-sidebar-primary: var(--sidebar-primary);
  --color-sidebar-primary-foreground: var(--sidebar-primary-foreground);
  --color-sidebar-accent: var(--sidebar-accent);
  --color-sidebar-accent-foreground: var(--sidebar-accent-foreground);
  --color-sidebar-border: var(--sidebar-border);
  --color-sidebar-ring: var(--sidebar-ring);
}

/* Custom recipe layout styles */
.recipe-hero {
  background: linear-gradient(135deg, var(--color-muted) 0%, var(--color-background) 100%);
}

.recipe-accent {
  color: var(--color-accent);
}

.recipe-divider {
  background: linear-gradient(90deg, var(--color-primary) 0%, transparent 100%);
  height: 2px;
}

/* Adding elegant category indicator styles */
.category-indicator {
  display: inline-flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1.5rem;
  border-radius: 2rem;
  background: oklch(0.98 0 0);
  border: 1px solid oklch(0.92 0 0);
  font-weight: 500;
  font-size: 0.875rem;
  letter-spacing: 0.025em;
  transition: all 0.2s ease;
}

.category-indicator:hover {
  background: oklch(0.96 0 0);
  border-color: oklch(0.88 0 0);
}

.category-dot {
  width: 0.75rem;
  height: 0.75rem;
  border-radius: 50%;
  flex-shrink: 0;
}

.category-daily {
  background: oklch(0.6 0.15 145);
  box-shadow: 0 0 0 2px oklch(0.6 0.15 145 / 0.2);
}

.category-occasional {
  background: oklch(0.65 0.18 85);
  box-shadow: 0 0 0 2px oklch(0.65 0.18 85 / 0.2);
}

.category-special {
  background: oklch(0.55 0.2 25);
  box-shadow: 0 0 0 2px oklch(0.55 0.2 25 / 0.2);
}

.nutrition-bar {
  background: oklch(0.95 0 0);
  border-radius: 8px;
  overflow: hidden;
  height: 8px;
  width: 100%;
}

.nutrition-segment {
  height: 8px;
  display: block;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.nutrition-protein {
  background: oklch(0.45 0.15 120);
}

.nutrition-carbs {
  background: oklch(0.55 0.2 60);
}

.nutrition-fats {
  background: oklch(0.35 0.1 30);
}

.nutrition-fiber {
  background: oklch(0.6 0.18 150);
}

/* Adding elegant recipe navigation styles */
.recipe-nav-button {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 3.5rem;
  height: 3.5rem;
  border-radius: 50%;
  background: oklch(0.98 0 0);
  border: 1px solid oklch(0.92 0 0);
  color: var(--color-foreground);
  transition: all 0.3s ease;
  backdrop-filter: blur(8px);
  box-shadow: 0 4px 12px oklch(0 0 0 / 0.1);
  position: relative;
}

.recipe-nav-button:hover {
  background: oklch(0.95 0 0);
  border-color: var(--color-primary);
  transform: scale(1.05);
  box-shadow: 0 6px 20px oklch(0 0 0 / 0.15);
}

.recipe-nav-button:active {
  transform: scale(0.95);
}

.recipe-nav-tooltip {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: var(--color-foreground);
  color: var(--color-background);
  padding: 0.5rem 0.75rem;
  border-radius: 0.5rem;
  font-size: 0.75rem;
  font-weight: 500;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: all 0.2s ease;
  z-index: 10;
}

.recipe-nav-button:hover .recipe-nav-tooltip {
  opacity: 1;
}

.recipe-nav-button:first-child .recipe-nav-tooltip {
  right: calc(100% + 0.75rem);
}

.recipe-nav-button:last-child .recipe-nav-tooltip {
  left: calc(100% + 0.75rem);
}

.recipe-indicator {
  width: 0.75rem;
  height: 0.75rem;
  border-radius: 50%;
  background: oklch(0.85 0 0);
  border: 2px solid oklch(0.92 0 0);
  transition: all 0.3s ease;
  cursor: pointer;
}

.recipe-indicator:hover {
  background: oklch(0.75 0 0);
  transform: scale(1.1);
}

.recipe-indicator.active {
  background: var(--color-primary);
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px oklch(0.205 0 0 / 0.2);
}

/* Adding elegant fade animations for recipe transitions */
.recipe-content {
  transition: opacity 0.3s ease-in-out, transform 0.3s ease-in-out;
  opacity: 1;
  transform: translateY(0);
}

.recipe-content.fade-out {
  opacity: 0;
  transform: translateY(-10px);
}

.recipe-content.fade-in {
  opacity: 1;
  transform: translateY(0);
}

/* Recipe stat badges for quick-scan information */
.recipe-stat-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: 1.5rem;
  background: oklch(0.98 0 0);
  border: 1px solid oklch(0.92 0 0);
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-foreground);
  transition: all 0.2s ease;
}

.recipe-stat-badge .stat-icon {
  font-size: 1rem;
  line-height: 1;
}

.recipe-stat-badge:hover {
  background: oklch(0.96 0 0);
  transform: translateY(-1px);
  box-shadow: 0 2px 8px oklch(0 0 0 / 0.1);
}

.stat-badge-success {
  background: oklch(0.95 0.05 145);
  border-color: oklch(0.6 0.15 145);
  color: oklch(0.3 0.1 145);
}

.stat-badge-info {
  background: oklch(0.95 0.05 240);
  border-color: oklch(0.6 0.15 240);
  color: oklch(0.3 0.1 240);
}

/* Ingredient section headers */
.ingredient-section-header {
  font-size: 1.125rem;
  font-weight: 600;
  font-family: var(--font-serif);
  color: var(--color-foreground);
  padding: 0.75rem 1rem;
  background: oklch(0.98 0 0);
  border-left: 3px solid var(--color-primary);
  border-radius: 0.375rem;
  margin-top: 0.5rem;
}

/* Empty instructions message styling */
.empty-instructions-message {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 3rem 2rem;
  border-radius: 1rem;
  background: linear-gradient(135deg, oklch(0.98 0 0) 0%, oklch(0.96 0 0) 100%);
  border: 2px dashed oklch(0.88 0 0);
}

.empty-message-icon {
  font-size: 3rem;
  line-height: 1;
  margin-bottom: 1rem;
  opacity: 0.8;
}

.empty-message-title {
  font-size: 1.5rem;
  font-weight: 600;
  font-family: var(--font-serif);
  color: var(--color-foreground);
  margin-bottom: 0.75rem;
}

.empty-message-text {
  font-size: 1rem;
  color: var(--color-muted-foreground);
  line-height: 1.6;
  max-width: 28rem;
}

/* Nutrition Card Styles - Minimalistic Apple Design */
.nutrition-card {
  background: oklch(0.99 0 0);
  border: 1px solid oklch(0.92 0 0);
  border-radius: 0.75rem;
  padding: 1.5rem;
  box-shadow: 0 1px 3px oklch(0 0 0 / 0.04);
  transition: none;
  animation: none;
}

.nutrition-card:hover {
  box-shadow: 0 1px 3px oklch(0 0 0 / 0.04);
  transform: none;
}

.nutrition-header {
  font-size: 1.25rem;
  font-weight: 600;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  color: var(--color-foreground);
  text-align: center;
  margin-bottom: 1.5rem;
  letter-spacing: -0.015em;
}

.nutrition-calories {
  text-align: center;
  margin-bottom: 1.5rem;
  padding: 1.25rem;
  background: oklch(0.985 0 0);
  border-radius: 0.625rem;
  border: 1px solid oklch(0.88 0 0);
}

.nutrition-calories-value {
  font-size: 2.5rem;
  font-weight: 600;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  color: oklch(0.3 0 0);
  line-height: 1;
  margin-bottom: 0.375rem;
  letter-spacing: -0.02em;
}

.nutrition-calories-label {
  font-size: 0.8125rem;
  font-weight: 500;
  color: oklch(0.5 0 0);
  text-transform: none;
  letter-spacing: 0;
}

.nutrition-macros-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}

.nutrition-macro-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 1rem;
  border-radius: 0.75rem;
  background: oklch(0.98 0 0);
  transition: all 0.3s ease;
}

.nutrition-macro-item:hover {
  transform: scale(1.05);
  background: oklch(0.96 0 0);
}

.nutrition-macro-item:nth-child(1) {
  animation-delay: 0.1s;
}

.nutrition-macro-item:nth-child(2) {
  animation-delay: 0.2s;
}

.nutrition-macro-item:nth-child(3) {
  animation-delay: 0.3s;
}

.nutrition-circle-progress {
  position: relative;
  width: 100px;
  height: 100px;
  margin-bottom: 1rem;
}

.nutrition-circle-background {
  fill: none;
  stroke: oklch(0.95 0 0);
  stroke-width: 8;
}

.nutrition-circle-fill {
  fill: none;
  stroke-width: 8;
  stroke-linecap: round;
  transform: rotate(-90deg);
  transform-origin: 50% 50%;
  transition: stroke-dashoffset 1s ease-out;
  animation: fillProgress 1.5s ease-out;
}

.nutrition-circle-fill.nutrition-protein {
  stroke: oklch(0.45 0.15 120);
}

.nutrition-circle-fill.nutrition-carbs {
  stroke: oklch(0.55 0.2 60);
}

.nutrition-circle-fill.nutrition-fats {
  stroke: oklch(0.35 0.1 30);
}

.nutrition-circle-text {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  font-size: 1.5rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--color-foreground);
}

.nutrition-macro-label {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-foreground);
  margin-bottom: 0.25rem;
  display: flex;
  align-items: center;
  gap: 0.25rem;
}

.nutrition-macro-value {
  font-size: 1.125rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--color-muted-foreground);
}

.nutrition-serving-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1rem;
  border-radius: 1.5rem;
  background: oklch(0.95 0.05 60);
  border: 1px solid oklch(0.6 0.15 60);
  font-size: 0.75rem;
  font-weight: 600;
  color: oklch(0.3 0.1 60);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin: 0 auto;
  display: flex;
  justify-content: center;
}

@keyframes slideInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fillProgress {
  from {
    stroke-dashoffset: 283;
  }
}

/* Responsive adjustments for nutrition card */
@media (max-width: 768px) {
  .nutrition-card {
    padding: 1.5rem;
  }

  .nutrition-macros-grid {
    grid-template-columns: 1fr;
    gap: 1rem;
  }

  .nutrition-circle-progress {
    width: 80px;
    height: 80px;
  }

  .nutrition-circle-text {
    font-size: 1.25rem;
  }

  .nutrition-calories-value {
    font-size: 2.5rem;
  }
}

@media (max-width: 640px) {
  .nutrition-macros-grid {
    grid-template-columns: 1fr;
  }
}

/* Respect reduced motion preferences */
@media (prefers-reduced-motion: reduce) {
  .nutrition-card,
  .nutrition-macro-item,
  .nutrition-circle-fill {
    animation: none;
    transition: none;
  }

  .nutrition-card:hover,
  .nutrition-macro-item:hover {
    transform: none;
  }
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

