  background: oklch(0.45 0.05 50);
}

.nutrition-macro-amount {
  font-size: 0.9375rem;
  font-weight: 600;
  color: oklch(0.3 0 0);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, sans-serif;
  letter-spacing: -0.01em;
  text-align: right;
}


/* Responsive adjustments for nutrition card */
@media (max-width: 768px) {
  .nutrition-card {
    padding: 1.25rem;
  }

  .nutrition-macros-grid {
    grid-template-columns: 1fr;
    gap: 0.75rem;
  }

  .nutrition-circle-progress {
    width: 70px;
    height: 70px;
  }

  .nutrition-circle-text {
    font-size: 1rem;
  }

  .nutrition-calories-value {
    font-size: 2rem;
  }
}

@media (max-width: 640px) {
  .nutrition-macros-grid {
    grid-template-columns: 1fr;
  }
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  body {
    @apply bg-background text-foreground;
  }
}

